-- Replace the shallow starter notes with a structured, in-site foundational study library.
-- All lessons below are independently authored; official portals are cited as alignment references only.
begin;

alter table public.external_exam_topics
  add column if not exists source_id uuid references public.external_exam_sources(id) on delete set null,
  add column if not exists source_locator text;

alter table public.external_exam_resources
  add column if not exists source_url text,
  add column if not exists content_origin text not null default 'unknown';

alter table public.external_exam_resources
  drop constraint if exists external_exam_resources_content_origin_check;
alter table public.external_exam_resources
  add constraint external_exam_resources_content_origin_check
  check (content_origin in ('original_prime_cbt','licensed_content','official_reference','unknown'));

-- Register the sources and their actual access/reuse limits. None of the exam-body
-- question papers or copyrighted syllabus text is copied by this migration.
insert into public.external_exam_sources
(publisher,source_name,source_kind,exam_code,source_url,edition_label,access_method,access_status,rights_status,rights_notes,is_active,last_verified_at)
select v.publisher,v.source_name,v.source_kind,v.exam_code,v.source_url,v.edition_label,v.access_method,v.access_status,v.rights_status,v.rights_notes,true,now()
from (values
 ('Joint Admissions and Matriculation Board','JAMB IBASS syllabus system','exam_body_syllabus','JAMB','https://ibass.jamb.gov.ng/','Official interactive syllabus portal','interactive_portal','publicly_accessible','permission_required','Official syllabus reference only. Interactive extraction has not been verified; do not bulk-copy content without permission.'),
 ('West African Examinations Council','WAEC e-Learning','official_elearning','WAEC','https://www.waeconline.org.ng/e-learning/','Official e-Learning reference','public_web','publicly_accessible','permission_required','WAEC pages display copyright notices. Use as a reference and link to source; do not republish question text or examiner reports without permission.'),
 ('National Examinations Council','NECO examinations and syllabus information','exam_body_syllabus','NECO','https://neco.gov.ng/exams','Current public examination information','public_web','publicly_accessible','permission_required','NECO lists its syllabus as a paid item. No complete free official syllabus has been verified; obtain the official syllabus before claiming NECO-specific alignment.'),
 ('Nigerian Educational Research and Development Council','NERDC Revised Senior Secondary Education Curriculum','curriculum_reference',null,'https://nerdc.gov.ng/content_manager/new_senior_curriculum_home.html','Revised SSS curriculum SS1–SS3','public_web','publicly_accessible','personal_study_only','Used only as a high-level topic cross-reference. It is not a JAMB, WAEC or NECO syllabus and its portal materials are marked for personal study. No curriculum text is copied into these original lessons.'),
 ('Siyavula Education','Siyavula open textbooks and learner resources','licensed_content',null,'https://ng.siyavula.com/read','Nigeria JSS Mathematics / Everything Maths and Science','public_web','publicly_accessible','licensed','Siyavula pages and individual editions carry different Creative Commons terms. Do not adapt CC BY-ND editions; verify the exact licence of each asset before reuse. Not copied by this migration.'),
 ('SdashAPI','SdashAPI Nigerian past-question API','licensed_content',null,'https://sdashapi.com/docs','V1 API documentation','licensed_feed','not_verified','permission_required','Third-party question feed, not an examination-body API. Commercial display requires an eligible paid plan. Do not mirror or export the raw dataset. API token and production plan have not yet been configured.')
) as v(publisher,source_name,source_kind,exam_code,source_url,edition_label,access_method,access_status,rights_status,rights_notes)
where not exists (
 select 1 from public.external_exam_sources x
 where x.source_url=v.source_url and x.edition_label=v.edition_label
);

-- Archive the first shallow batch; the new library below replaces it.
update public.external_exam_resources
set is_published=false, review_status='draft'
where source_label like 'PRIME-CBT original foundational lesson%';

update public.external_exam_topics
set is_published=false, review_status='draft'
where title in (
 'Reading comprehension and inference','Grammar: parts of speech and sentence structure',
 'Number operations, fractions and percentages','Algebraic expressions and linear equations',
 'Cell structure and organisation','Nutrition and energy in living organisms',
 'Atomic structure and the periodic table','Chemical bonding and simple compounds',
 'Motion, speed and acceleration','Electric current, voltage and resistance'
);

with subject_map(exam_code,subject_name,family) as (
 values
 ('JAMB','Use of English','english'),('JAMB','Mathematics','mathematics'),
 ('JAMB','Biology','biology'),('JAMB','Chemistry','chemistry'),('JAMB','Physics','physics'),
 ('WAEC','English Language','english'),('WAEC','General Mathematics','mathematics'),
 ('WAEC','Biology','biology'),('WAEC','Chemistry','chemistry'),('WAEC','Physics','physics'),
 ('NECO','English Language','english'),('NECO','General Mathematics','mathematics'),
 ('NECO','Biology','biology'),('NECO','Chemistry','chemistry'),('NECO','Physics','physics')
),
topic_seed(family,sort_order,title,description,objectives) as (
 values
 ('mathematics',10,'Number systems, sets and numerical reasoning','Build fluency with real numbers, fractions, decimals, percentages, ratio, proportion and set notation.','{Classify real numbers,Convert between fractions decimals and percentages,Solve ratio and proportion problems,Use set notation and Venn diagrams}'),
 ('mathematics',20,'Algebraic expressions, equations and inequalities','Translate statements into algebra, simplify expressions and solve linear and quadratic relationships.','{Collect like terms and expand brackets,Factorise common algebraic expressions,Solve linear and quadratic equations,Represent and solve inequalities}'),
 ('mathematics',30,'Indices, logarithms, surds and sequences','Apply laws of indices, simplify surds, use logarithms and recognise arithmetic and geometric patterns.','{Apply index laws including zero and negative powers,Simplify surds and rationalise simple denominators,Use logarithm laws,Find terms and sums of simple sequences}'),
 ('mathematics',40,'Geometry, mensuration and trigonometry','Reason about angles, polygons, circles, area, volume, bearings and right-triangle trigonometry.','{Use angle and polygon properties,Calculate perimeter area and volume,Apply Pythagoras theorem,Use sine cosine and tangent in right triangles}'),
 ('mathematics',50,'Statistics, graphs and probability','Organise data, interpret graphs, calculate averages and solve elementary probability problems.','{Calculate mean median mode and range,Interpret tables charts and frequency distributions,Use basic probability rules,Read and sketch linear graphs}'),

 ('english',10,'Reading comprehension and inference','Read passages accurately, identify central ideas, distinguish evidence from opinion and infer meaning from context.','{Identify main ideas and supporting details,Infer meaning using textual evidence,Recognise tone purpose and audience,Interpret vocabulary in context}'),
 ('english',20,'Grammar, clauses and sentence control','Use parts of speech, phrases, clauses, tense, agreement, punctuation and sentence structure accurately.','{Identify parts of speech and sentence functions,Apply subject verb agreement,Distinguish phrases and clauses,Correct tense and punctuation errors}'),
 ('english',30,'Lexis, semantics and structure','Develop vocabulary and understand synonyms, antonyms, idioms, collocations, register and contextual meaning.','{Choose words by context and register,Distinguish synonyms and antonyms,Interpret idioms and figurative expressions,Recognise collocation and word formation}'),
 ('english',40,'Summary and information selection','Condense a passage into precise points while preserving meaning and avoiding repetition or unnecessary examples.','{Identify relevant points,Paraphrase without changing meaning,Remove repetition and examples,Write concise grammatical sentences}'),
 ('english',50,'Continuous writing and oral English','Plan clear essays and letters, organise paragraphs and practise pronunciation, stress, rhythm and vowel/consonant distinctions.','{Plan introductions body and conclusions,Use appropriate formal and informal register,Build coherent paragraphs,Recognise common sound and stress patterns}'),

 ('biology',10,'Cell biology and organisation','Study cell structures, specialised cells, levels of organisation and the relationship between structure and function.','{Compare plant and animal cells,Relate organelles to their functions,Explain diffusion osmosis and active transport,Describe levels of biological organisation}'),
 ('biology',20,'Nutrition and food processing','Explain autotrophic and heterotrophic nutrition, photosynthesis, digestion, enzymes and balanced diets.','{State requirements and products of photosynthesis,Explain enzyme action and factors affecting it,Trace digestion and absorption,Relate nutrients to health}'),
 ('biology',30,'Transport, respiration and excretion','Understand transport systems in plants and animals, gas exchange, cellular respiration and removal of metabolic waste.','{Describe xylem and phloem transport,Explain blood circulation and gas exchange,Compare aerobic and anaerobic respiration,Identify excretory organs and their roles}'),
 ('biology',40,'Reproduction, inheritance and variation','Explore sexual and asexual reproduction, reproductive health, genes, chromosomes, inheritance and variation.','{Compare sexual and asexual reproduction,Describe human reproductive processes,Explain genes alleles and chromosomes,Use simple genetic crosses}'),
 ('biology',50,'Ecology, evolution and conservation','Study ecosystems, energy flow, nutrient cycles, population interactions, natural selection and biodiversity protection.','{Distinguish habitat niche and ecosystem,Interpret food chains and food webs,Explain population changes and adaptations,Discuss conservation and human impacts}'),

 ('chemistry',10,'Atomic structure and periodic classification','Explain subatomic particles, isotopes, electronic arrangement and periodic trends.','{Calculate protons neutrons and electrons,Interpret atomic and mass numbers,Write simple electronic configurations,Relate groups and periods to properties}'),
 ('chemistry',20,'Chemical bonding and structure','Compare ionic, covalent and metallic bonding and connect particle structure to material properties.','{Explain ionic and covalent bond formation,Draw simple electron-dot structures,Relate bonding to melting and boiling points,Distinguish intermolecular forces}'),
 ('chemistry',30,'Mole concept and chemical calculations','Use relative masses, the mole, balanced equations and concentration to solve quantitative chemistry problems.','{Calculate relative formula mass,Convert between mass moles and particles,Use mole ratios in balanced equations,Calculate simple solution concentrations}'),
 ('chemistry',40,'Acids, bases, salts and reactions','Classify acids and bases, use indicators and pH ideas, prepare salts and write balanced reaction equations.','{Identify acids bases and indicators,Interpret the pH scale,Describe neutralisation and salt preparation,Balance common chemical equations}'),
 ('chemistry',50,'Organic chemistry and environmental chemistry','Introduce hydrocarbons, functional groups, polymers, fuels, water treatment and chemical effects on the environment.','{Name simple alkanes alkenes and alcohols,Compare saturated and unsaturated compounds,Explain combustion and cracking,Discuss pollution and water treatment}'),

 ('physics',10,'Measurements, vectors and motion','Use SI units, significant figures, scalar and vector quantities, distance-time graphs and motion equations.','{Use SI base and derived units,Distinguish scalars and vectors,Interpret motion graphs,Calculate speed velocity and acceleration}'),
 ('physics',20,'Forces, momentum, work and energy','Apply Newton’s laws, resolve simple forces and use conservation ideas in work, power, momentum and energy.','{State and apply Newtons laws,Calculate resultant force and weight,Use work energy and power relationships,Apply momentum conservation in simple collisions}'),
 ('physics',30,'Heat, temperature and thermal processes','Distinguish heat from temperature and explain expansion, heat capacity, latent heat and modes of heat transfer.','{Convert common temperature scales,Explain thermal expansion,Use specific heat capacity and latent heat,Compare conduction convection and radiation}'),
 ('physics',40,'Waves, sound and geometrical optics','Describe wave properties, sound, reflection, refraction, lenses and image formation.','{Relate frequency wavelength and wave speed,Explain reflection and refraction,Use simple lens relationships,Describe sound properties and applications}'),
 ('physics',50,'Electricity, magnetism and electromagnetic induction','Understand charge, current, potential difference, resistance, circuit rules, magnetic fields and induction.','{Apply Ohms law,Compare series and parallel circuits,Explain magnetic fields around conductors,Describe electromagnetic induction and applications}')
),
subjects as (
 select s.id,s.exam_code,sm.family
 from subject_map sm join public.external_exam_subjects s
 on s.exam_code=sm.exam_code and s.name=sm.subject_name and s.is_active
),
new_topics as (
 insert into public.external_exam_topics
 (subject_id,title,description,learning_objectives,sort_order,is_published,review_status,reviewed_at,source_id,source_locator)
 select su.id,ts.title,ts.description,string_to_array(trim(both '{}' from ts.objectives),','),ts.sort_order,true,'editorial_reviewed',now(),
 (select id from public.external_exam_sources where source_url='https://nerdc.gov.ng/content_manager/new_senior_curriculum_home.html' limit 1),
 'Cross-curriculum reference only; not an examination-body syllabus'
 from subjects su join topic_seed ts on ts.family=su.family
 where not exists(select 1 from public.external_exam_topics t where t.subject_id=su.id and t.title=ts.title)
 returning id,subject_id,title
)
insert into public.external_exam_resources
(subject_id,topic_id,exam_code,resource_type,title,description,source_year,source_label,source_url,is_published,is_premium,
 content_markdown,key_points,learning_objectives,estimated_minutes,review_status,reviewed_at,rights_status,content_origin,content_version)
select
 su.id,t.id,su.exam_code,'lesson',t.title,
 t.description,null,
 'Original PRIME-CBT lesson. Topic selection cross-references the NERDC revised Senior Secondary curriculum; this is not a JAMB, WAEC or NECO-issued syllabus.',
 'https://nerdc.gov.ng/content_manager/new_senior_curriculum_home.html',
 true,false,
 case t.title
 when 'Number systems, sets and numerical reasoning' then E'# Number systems, sets and numerical reasoning\n\n## 1. The real number system\nReal numbers include rational and irrational numbers. Rational numbers can be written as a ratio of integers with a non-zero denominator; examples include -3, 0.25 and 7/9. Irrational numbers cannot be expressed as such a ratio; examples include √2 and π. Every integer is rational, but not every rational number is an integer.\n\n## 2. Fractions, decimals and percentages\nA percentage means a quantity out of 100. To convert a fraction to a percentage, multiply by 100%. To convert a percentage to a decimal, divide by 100. For example, 3/5 = 0.6 = 60%. When finding 15% of ₦8,000, calculate 0.15 × 8,000 = ₦1,200.\n\n## 3. Ratio and proportion\nA ratio compares quantities in the same units. Simplify 18:24 by dividing both terms by 6 to obtain 3:4. If 3 notebooks cost ₦900, the unit cost is ₦300 and 7 notebooks cost ₦2,100, assuming a constant price. Direct proportion increases at the same rate; inverse proportion decreases as the other quantity increases.\n\n## 4. Sets and Venn diagrams\nA set is a well-defined collection. The union A ∪ B contains elements in A or B or both. The intersection A ∩ B contains elements common to both. The complement contains elements in the universal set that are not in the set. Use a Venn diagram to avoid double-counting when groups overlap.\n\n## Worked example\nIn a class of 40 learners, 24 study Biology, 18 study Chemistry and 10 study both. The number studying at least one is 24 + 18 − 10 = 32. The number studying neither is 40 − 32 = 8.\n\n## Exam approach\nWrite units beside quantities, simplify ratios before using them, and check whether a word problem describes direct or inverse proportion.'
 when 'Algebraic expressions, equations and inequalities' then E'# Algebraic expressions, equations and inequalities\n\n## Expressions and terms\nAn algebraic expression combines numbers, variables and operations. In 5x − 3y + 8, the terms are 5x, −3y and 8. Like terms have the same variable part and powers: 4a + 7a = 11a, but 4a + 7a² cannot be combined.\n\n## Expanding and factorising\nThe distributive law gives a(b + c) = ab + ac. Thus 3(2x − 5) = 6x − 15. Factorisation reverses expansion: 6x + 15 = 3(2x + 5). Always check by expanding the factorised result.\n\n## Linear equations\nKeep an equation balanced by performing the same operation on both sides. Solve 4x − 7 = 13: add 7 to get 4x = 20, then divide by 4, so x = 5. Substitute x = 5 into the original equation to verify 20 − 7 = 13.\n\n## Simultaneous equations\nFor x + y = 9 and x − y = 3, add the equations to eliminate y: 2x = 12, so x = 6. Substitute into x + y = 9 to obtain y = 3.\n\n## Quadratic equations\nA quadratic has the form ax² + bx + c = 0, where a ≠ 0. Factorise when possible. For x² − 5x + 6 = 0, (x − 2)(x − 3) = 0, so x = 2 or x = 3. The quadratic formula works when factorisation is not straightforward.\n\n## Inequalities\nSolve inequalities like equations, but reverse the inequality sign when multiplying or dividing by a negative number. From −2x > 6, divide by −2 and reverse the sign: x < −3.'
 when 'Indices, logarithms, surds and sequences' then E'# Indices, logarithms, surds and sequences\n\n## Laws of indices\nFor non-zero a, aᵐ × aⁿ = aᵐ⁺ⁿ, aᵐ ÷ aⁿ = aᵐ⁻ⁿ, and (aᵐ)ⁿ = aᵐⁿ. Also a⁰ = 1 and a⁻ⁿ = 1/aⁿ. For example, 2³ × 2² = 2⁵ = 32. Apply laws only when the bases are the same.\n\n## Surds\nA surd is an irrational root left in exact form. Simplify √72 by writing 72 = 36 × 2, so √72 = 6√2. Like surds can be added: 3√5 + 2√5 = 5√5, but √2 and √3 cannot be combined.\n\n## Logarithms\nA logarithm answers the question: to what power must a base be raised to obtain a number? log₁₀(1000) = 3 because 10³ = 1000. The product law is log(ab) = log(a) + log(b); the quotient law is log(a/b) = log(a) − log(b), for positive arguments and a valid base.\n\n## Sequences\nAn arithmetic sequence has a constant difference d. Its nth term is aₙ = a + (n − 1)d. For 4, 7, 10, 13, the first term is 4 and d = 3; the 10th term is 4 + 9(3) = 31. A geometric sequence has a constant ratio r and nth term aₙ = arⁿ⁻¹.\n\n## Common mistakes\nDo not add indices when adding terms, do not treat √(a + b) as √a + √b, and distinguish the common difference of an arithmetic sequence from the common ratio of a geometric sequence.'
 when 'Geometry, mensuration and trigonometry' then E'# Geometry, mensuration and trigonometry\n\n## Angles and polygons\nAngles on a straight line add to 180°, angles around a point add to 360°, and vertically opposite angles are equal. The interior angle sum of an n-sided polygon is (n − 2) × 180°. A regular polygon has equal sides and equal interior angles.\n\n## Triangles and Pythagoras\nThe interior angles of a triangle add to 180°. In a right-angled triangle, a² + b² = c², where c is the hypotenuse. If the shorter sides are 6 cm and 8 cm, the hypotenuse is √(36 + 64) = 10 cm.\n\n## Mensuration\nArea of a rectangle = length × width; triangle = ½ × base × height; circle = πr². Circumference of a circle = 2πr. Volume of a cuboid = lwh and volume of a cylinder = πr²h. Convert all measurements to consistent units before substituting.\n\n## Trigonometric ratios\nFor an acute angle θ in a right triangle: sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse and tan θ = opposite/adjacent. Remember SOH–CAH–TOA. Use the inverse ratios on a calculator to find an angle.\n\n## Bearings and elevation\nBearings are measured clockwise from north and written with three digits, for example 065°. An angle of elevation is measured upward from the horizontal; an angle of depression is measured downward. Draw and label a diagram before using trigonometry.\n\n## Check your answer\nArea is measured in square units and volume in cubic units. A length cannot be reported in cm². Check whether the question asks for an exact answer in terms of π or a decimal approximation.'
 when 'Statistics, graphs and probability' then E'# Statistics, graphs and probability\n\n## Organising data\nA frequency table records how often each value or class occurs. A bar chart compares categories; a histogram represents grouped continuous data with adjoining bars. Read the axis labels and scales before interpreting a graph.\n\n## Measures of central tendency\nThe mean is total divided by number of observations. The median is the middle value after sorting; for an even number of values, average the two middle values. The mode is the most frequent value. The range is maximum minus minimum. For 2, 3, 3, 7, 10, the mean is 5, median is 3, mode is 3 and range is 8.\n\n## Probability\nFor equally likely outcomes, P(A) = favourable outcomes / total outcomes. Probability lies between 0 and 1. The complement rule is P(not A) = 1 − P(A). For mutually exclusive events, P(A or B) = P(A) + P(B). For independent events, P(A and B) = P(A) × P(B).\n\n## Worked example\nA fair die has six equally likely outcomes. The probability of rolling an even number is 3/6 = 1/2. The probability of not rolling a six is 5/6.\n\n## Graphs\nFor a straight line y = mx + c, m is the gradient and c is the vertical intercept. Gradient = change in y / change in x. A positive gradient rises from left to right; a negative gradient falls. Use two well-separated points on the line when calculating gradient.'
 when 'Reading comprehension and inference' then E'# Reading comprehension and inference\n\n## Read for meaning\nFirst read the passage to understand its subject and overall message. On a second reading, identify the paragraph or sentence that supports each answer. The best comprehension answer is the one justified by the passage, not simply the one that sounds reasonable in everyday life.\n\n## Main idea and supporting details\nThe main idea is the central point the writer develops. Supporting details may be examples, facts, explanations or comparisons. A title often summarises the main idea but should not be narrower than the whole passage.\n\n## Inference\nAn inference is a conclusion drawn from clues. It is not a guess and must not introduce facts that the passage does not support. If a passage says a market became quiet after heavy rain, you may infer that fewer people visited; you cannot infer that the market was permanently closed.\n\n## Tone, purpose and audience\nTone describes the writer’s attitude, such as critical, sympathetic, humorous or optimistic. Purpose may be to inform, persuade, explain, entertain or warn. Audience refers to the readers the writer addresses. Use word choice and the passage context as evidence.\n\n## Vocabulary in context\nWhen asked for the meaning of a word, replace it with each option and reread the sentence. The correct synonym must fit the meaning and grammar of that particular context.\n\n## Exam technique\nRead the question carefully, locate the evidence, eliminate unsupported options and avoid spending too long on one item.'
 when 'Grammar, clauses and sentence control' then E'# Grammar, clauses and sentence control\n\n## Parts of speech\nNouns name people, places, things or ideas. Pronouns replace nouns. Verbs express actions or states. Adjectives describe nouns; adverbs modify verbs, adjectives or other adverbs. Prepositions show relationships, while conjunctions connect words, phrases or clauses.\n\n## Phrases and clauses\nA phrase is a group of words functioning as a unit but without a complete subject–finite verb relationship. A clause contains a subject and a verb. An independent clause can stand alone; a dependent clause needs another clause to complete its meaning.\n\n## Subject–verb agreement\nA singular subject normally takes a singular verb: The list of items is on the table. The verb agrees with the head subject, not a nearby noun. With either/or and neither/nor, agreement commonly follows the nearer subject.\n\n## Tense and sequence\nKeep tense consistent unless the time meaning changes. Use the present perfect for an action connected to the present, and the simple past for a completed past time. Avoid shifting tense without reason.\n\n## Punctuation\nA comma separates items or clauses where required; a semicolon can join closely related independent clauses; a colon introduces an explanation or list. An apostrophe marks possession or omitted letters, not ordinary plurals.\n\n## Editing checklist\nCheck agreement, tense, pronoun reference, sentence boundaries, punctuation and spelling. Read the sentence aloud to detect awkward or incomplete construction.'
 when 'Lexis, semantics and structure' then E'# Lexis, semantics and structure\n\nLexis concerns vocabulary and word choice. A word’s meaning depends on context, register and the relationship it has with nearby words. In a formal report, “purchase” may be more suitable than “buy”; the choice depends on audience and purpose.\n\n## Synonyms and antonyms\nA synonym has a similar meaning, while an antonym has an opposite meaning. They are rarely interchangeable in every context. “Slim” and “thin” are close in meaning, but their tone can differ. Choose the option that fits the sentence.\n\n## Idioms and figurative language\nAn idiom has a conventional meaning that may not be predictable from its individual words. “Break the ice” means to make people feel more comfortable, not to break frozen water. Metaphor and personification also communicate meaning beyond literal wording.\n\n## Word formation\nPrefixes and suffixes alter meaning or grammatical function. “Un-” can express negation; “-ness” can turn an adjective into a noun. Recognising roots and affixes helps decode unfamiliar words.\n\n## Collocation and register\nSome words naturally occur together: “make a decision” and “heavy rain”. Register refers to the level of formality. Avoid slang in formal letters and reports unless the task specifically calls for informal language.\n\n## Exam method\nUse the surrounding sentence, the writer’s purpose and the grammatical role of the missing word to eliminate unsuitable options.'
 when 'Summary and information selection' then E'# Summary and information selection\n\nA summary presents only the important points of a passage in fewer words. It should preserve the writer’s meaning while removing repetition, examples and minor details. It is not a personal opinion or a commentary on the passage.\n\n## A reliable method\n1. Read the full passage to understand its central subject.\n2. Read the instruction and note the number of points or word limit.\n3. Identify sentences that express distinct, relevant ideas.\n4. Combine related points without changing their meaning.\n5. Paraphrase in clear, grammatical sentences.\n6. Check that each sentence adds a new point.\n\n## Paraphrasing\nReplace wording with accurate alternatives and change sentence structure where possible. Do not merely swap one word while copying the original sentence. Technical terms may need to remain unchanged if replacing them would distort the meaning.\n\n## Avoid these errors\nDo not add information from outside the passage. Do not repeat the same idea in different words. Do not include long examples when the general point is sufficient. Do not begin every point with “The passage says”.\n\n## Practice strategy\nAfter writing, compare each sentence with the passage and ask: Is this point relevant? Is it distinct? Is it accurate? Can it be expressed more briefly?'
 when 'Continuous writing and oral English' then E'# Continuous writing and oral English\n\n## Plan before writing\nIdentify the task type, audience, purpose and required tone. A narrative tells a story; an argumentative essay defends a position; an expository essay explains; a descriptive essay creates a clear impression. A formal letter follows conventions that differ from an informal letter.\n\n## Structure\nA strong essay has an introduction that establishes the subject, body paragraphs that develop separate points and a conclusion that brings the argument or explanation together. Each paragraph should have one controlling idea supported by examples or explanation. Use transitions to show relationships between points.\n\n## Letters\nA formal letter uses an appropriate address, date, salutation, clear subject or opening, organised body and suitable closing. An informal letter may use a warmer tone, but it should still be coherent and correctly punctuated. Follow the exact format taught for the exam paper.\n\n## Oral English\nSpeech sounds are not always represented by one letter. Learn the difference between vowels and consonants, voiced and voiceless sounds, syllables, word stress and sentence intonation. A stressed syllable is more prominent; changing stress can change meaning or grammatical function.\n\n## Editing\nCheck that you answered the exact question, stayed within the expected length, used paragraphs, avoided repetition and corrected grammar and spelling.'
 when 'Cell biology and organisation' then E'# Cell biology and organisation\n\n## The cell\nThe cell is the basic structural and functional unit of living organisms. Prokaryotic cells lack a membrane-bound nucleus; eukaryotic cells contain one. Plant and animal cells are both eukaryotic, but typical plant cells have a cellulose cell wall, chloroplasts in photosynthetic tissues and a large permanent vacuole.\n\n## Cell structures\nThe cell membrane regulates movement into and out of the cell. The nucleus contains genetic material and helps control cell activities. Mitochondria are major sites of aerobic respiration. Ribosomes make proteins. Chloroplasts contain chlorophyll and are the sites of photosynthesis in green plant cells.\n\n## Movement across membranes\nDiffusion is net movement of particles from higher to lower concentration. Osmosis is movement of water through a selectively permeable membrane from a region of higher water potential to lower water potential. Active transport moves substances against a concentration gradient using energy.\n\n## Specialisation and organisation\nA specialised cell has structures suited to its role. Red blood cells transport oxygen; root hair cells absorb water and mineral ions; palisade cells contain many chloroplasts. Cells form tissues, tissues form organs and organs work together in systems.\n\n## Exam focus\nBe able to compare plant and animal cells, identify organelles on diagrams and explain how surface area, membrane structure and concentration gradients affect transport.'
 when 'Nutrition and food processing' then E'# Nutrition and food processing\n\n## Autotrophic nutrition\nGreen plants make organic food by photosynthesis. In simplified form: carbon dioxide + water → glucose + oxygen, in the presence of light and chlorophyll. Light energy is converted into chemical energy stored in glucose. Factors affecting the rate include light intensity, carbon dioxide concentration and temperature.\n\n## Heterotrophic nutrition\nAnimals obtain ready-made organic nutrients by feeding. A balanced diet supplies carbohydrates, proteins, fats, vitamins, minerals, fibre and water in suitable amounts. Carbohydrates are a major energy source; proteins support growth and repair; fats provide concentrated energy and insulation.\n\n## Digestion\nDigestion breaks large insoluble food molecules into smaller soluble molecules. Amylase acts on starch; proteases act on proteins; lipases act on fats. The small intestine is adapted for absorption by having a large surface area, thin epithelium and a rich blood supply.\n\n## Enzymes\nEnzymes are biological catalysts. Each enzyme has an active site that binds a suitable substrate. Temperature and pH affect enzyme activity; extreme conditions can alter the active site and denature the enzyme.\n\n## Study check\nDistinguish ingestion, digestion, absorption, assimilation and egestion. They describe different stages and should not be used interchangeably.'
 when 'Transport, respiration and excretion' then E'# Transport, respiration and excretion\n\n## Transport in plants\nXylem transports water and mineral ions mainly from roots towards leaves and also provides support. Phloem transports dissolved products of photosynthesis from sources to sinks; movement can occur in different directions depending on demand. Transpiration is water loss from aerial plant surfaces, mainly through stomata.\n\n## Transport in humans\nThe circulatory system includes the heart, blood and blood vessels. Arteries carry blood away from the heart, veins return blood and capillaries allow exchange with tissues. Red blood cells contain haemoglobin for oxygen transport; plasma carries dissolved substances.\n\n## Respiration\nAerobic respiration releases energy from glucose using oxygen: glucose + oxygen → carbon dioxide + water + energy. Anaerobic respiration releases less energy without oxygen; in human muscles it produces lactate, while yeast produces ethanol and carbon dioxide.\n\n## Gas exchange\nEfficient exchange surfaces are thin, moist and have a large surface area with a good transport system. In the lungs, alveoli provide a large surface area and a short diffusion distance.\n\n## Excretion\nExcretion removes metabolic waste, such as carbon dioxide and urea. The kidneys filter blood, selectively reabsorb useful substances and help regulate water and salt balance. Egestion is removal of undigested food and is not the same as excretion.'
 when 'Reproduction, inheritance and variation' then E'# Reproduction, inheritance and variation\n\n## Reproduction\nAsexual reproduction involves one parent and usually produces genetically similar offspring. Sexual reproduction involves fusion of male and female gametes and creates genetic variation. In flowering plants, pollination transfers pollen to a stigma; fertilisation occurs when the male nucleus fuses with the egg nucleus.\n\n## Human reproduction\nThe testes produce sperm and testosterone; the ovaries produce ova and hormones. Fertilisation usually occurs in the oviduct. The developing embryo implants in the uterus. Reproductive health includes hygiene, informed decision-making and prevention and treatment of sexually transmitted infections.\n\n## Inheritance\nGenes are sections of DNA located on chromosomes. Different forms of a gene are alleles. In a simple dominant–recessive model, a dominant allele can determine the phenotype in a heterozygote, while a recessive phenotype appears when two recessive alleles are present.\n\n## Simple genetic cross\nLet T represent a dominant tall allele and t a recessive short allele. A cross Tt × Tt gives possible genotypes TT, Tt, Tt and tt. The genotype ratio is 1:2:1 and the phenotype ratio is 3 tall:1 short, assuming complete dominance and equal probability.\n\n## Variation\nVariation may be genetic, environmental or a combination. Mutation creates new genetic variants; meiosis and fertilisation reshuffle alleles. Natural selection can change the frequency of inherited traits over generations.'
 when 'Ecology, evolution and conservation' then E'# Ecology, evolution and conservation\n\n## Ecological organisation\nAn organism lives in a habitat and occupies a niche, describing its role and interactions. A population is members of one species in an area; a community contains interacting populations; an ecosystem includes the community and its physical environment.\n\n## Energy flow\nProducers convert light energy into chemical energy. Consumers obtain energy by feeding, and decomposers break down dead material. Food chains show feeding relationships; food webs combine interconnected chains. Energy is lost between trophic levels through respiration, heat and waste, so less energy is available at higher levels.\n\n## Population change\nPopulation size is influenced by births, deaths, immigration and emigration. Competition occurs when organisms need the same limited resource. Predation, disease, climate and habitat availability can also affect population size.\n\n## Adaptation and evolution\nAn adaptation is an inherited feature that improves survival or reproductive success in a particular environment. Natural selection occurs when individuals with advantageous heritable variations leave more offspring over generations. Individuals do not evolve because they choose to; populations change over generations.\n\n## Conservation\nHabitat destruction, pollution, overexploitation and invasive species threaten biodiversity. Conservation strategies include protected areas, habitat restoration, sustainable harvesting and environmental education.'
 when 'Atomic structure and periodic classification' then E'# Atomic structure and periodic classification\n\n## Subatomic particles\nAtoms contain protons and neutrons in the nucleus, with electrons occupying energy levels around it. A proton has relative charge +1, an electron −1 and a neutron 0. Atomic number is the number of protons. Mass number is the total number of protons and neutrons.\n\n## Isotopes\nIsotopes are atoms of the same element with equal proton numbers but different neutron numbers. They have similar chemical properties because they have the same electron arrangement, but their masses differ.\n\n## Electronic arrangement\nElectrons occupy shells or energy levels. For the first 20 elements, a simplified shell pattern is commonly written 2, 8, 8, 2. The outer-shell electrons are important in chemical bonding and help explain group behaviour.\n\n## Periodic table\nA period is a horizontal row and a group is a vertical column. Elements in the same main group have similar outer electron arrangements and often similar chemical properties. Across a period, nuclear charge generally increases; down a group, additional electron shells are occupied.\n\n## Worked example\nAn atom with atomic number 11 has 11 protons and, if neutral, 11 electrons. If its mass number is 23, it has 23 − 11 = 12 neutrons.'
 when 'Chemical bonding and structure' then E'# Chemical bonding and structure\n\n## Ionic bonding\nIonic bonding involves electron transfer, usually from a metal to a non-metal. The resulting positive and negative ions attract electrostatically. Sodium chloride contains Na⁺ and Cl⁻ ions arranged in a giant ionic lattice. Ionic compounds often have high melting points and conduct electricity when molten or dissolved because ions can move.\n\n## Covalent bonding\nCovalent bonding involves sharing electron pairs between atoms, commonly non-metals. A water molecule has two O–H covalent bonds. Simple molecular substances often have relatively low melting and boiling points because the forces between molecules are weaker than the covalent bonds within molecules.\n\n## Metallic bonding\nMetals consist of positive ions in a lattice surrounded by delocalised electrons. The mobile electrons help explain electrical and thermal conductivity. Layers of metal ions can slide while metallic bonding remains, helping explain malleability.\n\n## Structure and properties\nDistinguish strong bonds within a structure from forces between molecules. This distinction helps explain why a molecular substance can have strong covalent bonds but a low boiling point.\n\n## Formula writing\nIonic formulae show the simplest ratio of ions that gives an overall neutral compound. Magnesium forms Mg²⁺ and chloride forms Cl⁻, so the formula is MgCl₂.'
 when 'Mole concept and chemical calculations' then E'# Mole concept and chemical calculations\n\n## Relative mass\nRelative atomic mass (Ar) compares the average mass of an atom with one-twelfth of the mass of a carbon-12 atom. Relative formula mass (Mr) is the sum of the relative atomic masses in a formula. For H₂O, Mr = 2(1) + 16 = 18.\n\n## The mole\nOne mole contains approximately 6.02 × 10²³ specified particles. Amount of substance n = mass m / molar mass M. If 36 g of water has molar mass 18 g mol⁻¹, n = 36/18 = 2 mol.\n\n## Balanced equations\nA balanced equation has equal numbers of each type of atom on both sides. Coefficients show mole ratios. In 2H₂ + O₂ → 2H₂O, two moles of hydrogen react with one mole of oxygen to produce two moles of water.\n\n## Concentration\nFor a solution, concentration in mol dm⁻³ = amount in mol / volume in dm³. Convert cm³ to dm³ by dividing by 1000. A 0.2 mol solution in 0.5 dm³ has concentration 0.4 mol dm⁻³.\n\n## Calculation method\nWrite the balanced equation, convert the known quantity to moles, use the coefficient ratio, then convert to the requested unit. Keep units throughout and round only at the end.'
 when 'Acids, bases, salts and reactions' then E'# Acids, bases, salts and reactions\n\n## Acids and bases\nIn aqueous solution, an acid produces hydrogen ions, while a base accepts hydrogen ions or neutralises an acid. Alkalis are soluble bases that produce hydroxide ions in water. Indicators change colour over a pH range; universal indicator gives an approximate pH.\n\n## pH\npH is a measure related to hydrogen-ion concentration. A pH below 7 is acidic, 7 is neutral at ordinary reference conditions and above 7 is alkaline. A change of one pH unit represents a tenfold change in hydrogen-ion concentration.\n\n## Neutralisation\nAn acid reacts with a base to form a salt and water. For example, hydrochloric acid + sodium hydroxide → sodium chloride + water. The net ionic equation is H⁺ + OH⁻ → H₂O.\n\n## Preparing salts\nSoluble salts may be prepared by reacting an acid with a suitable insoluble base or carbonate, then filtering excess solid and crystallising the solution. A salt can also be prepared by titration when both reactants are soluble.\n\n## Chemical equations\nWrite correct formulae first, then balance atoms using coefficients. Never change subscripts to balance an equation because that changes the identity of the substance.'
 when 'Organic chemistry and environmental chemistry' then E'# Organic chemistry and environmental chemistry\n\n## Hydrocarbons\nHydrocarbons contain only carbon and hydrogen. Alkanes are saturated and contain carbon–carbon single bonds; alkenes contain at least one carbon–carbon double bond. The general formula for an open-chain alkane is CₙH₂ₙ₊₂ and for an open-chain alkene with one double bond is CₙH₂ₙ.\n\n## Reactions and uses\nAlkanes commonly undergo combustion and substitution. Alkenes undergo addition reactions because the double bond can open to form new bonds. Bromine water is decolourised by many unsaturated compounds and can be used as a test for a carbon–carbon double bond.\n\n## Functional groups\nAn alcohol contains a hydroxyl group (−OH); a carboxylic acid contains a carboxyl group (−COOH). Functional groups influence chemical reactions and physical properties. Learn to recognise simple structural formulae.\n\n## Fuels and pollution\nComplete combustion in sufficient oxygen produces carbon dioxide and water. Incomplete combustion can produce carbon monoxide and soot. Carbon monoxide is toxic because it reduces the blood’s ability to transport oxygen.\n\n## Environmental chemistry\nWater treatment may involve screening, sedimentation, filtration and disinfection. Fertilisers can improve crop yields, but runoff may cause eutrophication. Reduce pollution through efficient processes, safe waste treatment and responsible resource use.'
 when 'Measurements, vectors and motion' then E'# Measurements, vectors and motion\n\n## Measurement\nPhysics uses agreed SI units. Length is measured in metres, mass in kilograms, time in seconds and electric current in amperes. Derived units combine base units; speed is measured in m s⁻¹ and acceleration in m s⁻². Record measurements with sensible precision and use significant figures consistently.\n\n## Scalars and vectors\nA scalar has magnitude only, such as mass, time or speed. A vector has magnitude and direction, such as displacement, velocity, acceleration and force. Distance is total path length; displacement is the straight-line change in position with direction.\n\n## Speed and velocity\nAverage speed = total distance / total time. Average velocity = displacement / time. Acceleration = change in velocity / time. A negative acceleration does not always mean an object is slowing down; direction matters.\n\n## Motion graphs\nThe gradient of a distance–time graph gives speed. The gradient of a displacement–time graph gives velocity. The gradient of a velocity–time graph gives acceleration, while the area under it gives displacement.\n\n## Equations for constant acceleration\nv = u + at; s = ut + ½at²; v² = u² + 2as. Use these only when acceleration is constant and symbols are defined consistently.'
 when 'Forces, momentum, work and energy' then E'# Forces, momentum, work and energy\n\n## Newton’s laws\nA resultant force changes an object’s motion. Newton’s first law describes inertia; the second law gives F = ma for constant mass; the third law states that interacting bodies exert equal and opposite forces on each other. Action–reaction forces act on different bodies, so they do not cancel on one object.\n\n## Weight and friction\nWeight is gravitational force: W = mg. Mass is measured in kilograms and weight in newtons. Friction opposes relative motion or the tendency to move between surfaces. Draw a free-body diagram to show all forces acting on an object.\n\n## Work, energy and power\nWork done by a constant force along the direction of motion is W = Fd. Kinetic energy is ½mv² and gravitational potential energy near Earth is mgh. Power is the rate of doing work: P = W/t.\n\n## Momentum\nMomentum p = mv. In an isolated system, total momentum before an interaction equals total momentum after it. Use a consistent sign convention for direction.\n\n## Problem method\nDraw the situation, list known quantities with units, choose the relevant law and rearrange before substituting numbers. Check that the final unit matches the quantity requested.'
 when 'Heat, temperature and thermal processes' then E'# Heat, temperature and thermal processes\n\n## Heat and temperature\nTemperature indicates how hot or cold a body is and is related to the average kinetic energy of its particles. Heat is energy transferred because of a temperature difference. A body contains internal energy; heat is energy in transit.\n\n## Thermal expansion\nMost materials expand when heated and contract when cooled. Linear expansion is often approximated by ΔL = αL₀ΔT, where α is the coefficient of linear expansion. Expansion gaps are important in bridges and railway tracks.\n\n## Heat capacity\nThe heat needed to change temperature is Q = mcΔT, where m is mass, c is specific heat capacity and ΔT is temperature change. During a change of state, Q = mL, where L is specific latent heat; temperature remains constant while energy changes the state.\n\n## Transfer of heat\nConduction transfers energy through particle interactions, convection involves bulk movement of fluids, and radiation transfers energy by electromagnetic waves and can occur through a vacuum.\n\n## Calculations\nUse kilograms, joules and kelvin or degrees Celsius for temperature differences as appropriate. A temperature change of 10°C is equal in size to a change of 10 K.'
 when 'Waves, sound and geometrical optics' then E'# Waves, sound and geometrical optics\n\n## Wave properties\nA wave transfers energy without overall transfer of matter. Frequency f is the number of complete cycles per second; wavelength λ is the distance between corresponding points; amplitude is maximum displacement. Wave speed v = fλ.\n\n## Sound\nSound is a mechanical longitudinal wave and needs a medium. Its speed depends on the medium and conditions. Pitch depends mainly on frequency; loudness relates to intensity and amplitude. Echoes are reflected sound waves.\n\n## Reflection and refraction\nThe law of reflection states that angle of incidence equals angle of reflection, measured from the normal. Refraction is a change in direction caused by a change in wave speed as it crosses a boundary. Light entering a denser optical medium bends towards the normal when its speed decreases.\n\n## Lenses\nA converging lens brings parallel rays towards a focus; a diverging lens spreads them. The principal focus and focal length describe the lens. Ray diagrams help locate images and determine whether they are real or virtual, upright or inverted, magnified or diminished.\n\n## Exam technique\nDraw the normal at the point of incidence, measure angles from the normal rather than the surface, and label image distances and focal length clearly.'
 when 'Electricity, magnetism and electromagnetic induction' then E'# Electricity, magnetism and electromagnetic induction\n\n## Electric quantities\nCurrent I is the rate of flow of charge: I = Q/t. Potential difference is energy transferred per unit charge. Resistance measures opposition to current. Ohm’s law states V = IR for an ohmic conductor at constant physical conditions.\n\n## Circuits\nIn a series circuit, the current is the same through each component and supply voltage is shared. In a parallel circuit, each branch has the same potential difference and the total current is the sum of branch currents. For series resistors, Rₜ = R₁ + R₂; for parallel resistors, 1/Rₜ = 1/R₁ + 1/R₂.\n\n## Electrical power\nPower P = VI = I²R = V²/R. Electrical energy transferred is E = Pt. Use SI units: watts for power, joules for energy and seconds for time.\n\n## Magnetism\nA current-carrying conductor produces a magnetic field. The field direction around a straight wire can be found using the right-hand grip rule. A solenoid produces a field similar to that of a bar magnet.\n\n## Electromagnetic induction\nA changing magnetic flux through a coil induces an electromotive force. The induced effect opposes the change producing it (Lenz’s law). Generators use induction to convert mechanical energy into electrical energy.'
 else E'# Study guide\n\nThis original PRIME-CBT lesson introduces the topic and its key examination skills. Work through the definitions, understand the worked examples and practise applying each idea to unfamiliar situations.\n\n## How to study\nRead the learning objectives first. Write down important terms and formulae, then explain them in your own words. Work through examples without looking at the solution. Finally, attempt topic-based questions and review any errors.\n\n## Revision checklist\n- Define the key terms accurately.\n- Explain the process or principle in the correct order.\n- Apply the relevant formula or rule with units.\n- Interpret diagrams, tables and graphs carefully.\n- Check that your answer addresses the exact question asked.',
 array['Read the lesson and learning objectives before attempting questions','Write down key definitions and formulae','Practise with worked examples and explain each step','Check the final answer and units'],
 string_to_array(trim(both '{}' from (select objectives from topic_seed ts where ts.family=su.family and ts.title=t.title)),','),
 18,'editorial_reviewed',now(),'original','original_prime_cbt',2
from new_topics t
join subjects su on su.id=t.subject_id
join topic_seed ts on ts.family=su.family and ts.title=t.title
where not exists(select 1 from public.external_exam_resources r where r.topic_id=t.id and r.is_published);

-- Store the curriculum references as explicitly unverified cross-exam topic alignments.
insert into public.external_exam_syllabus_entries
(source_id,exam_code,subject_id,linked_topic_id,entry_kind,title,source_locator,edition_label,alignment_status,review_notes,is_published,sort_order)
select
 (select id from public.external_exam_sources where source_url='https://nerdc.gov.ng/content_manager/new_senior_curriculum_home.html' limit 1),
 s.exam_code,s.id,t.id,'topic',t.title,
 'https://nerdc.gov.ng/content_manager/new_senior_curriculum_home.html',
 'NERDC revised SSS curriculum reference; cross-exam mapping only',
 'needs_clarification',
 'This is a broad curriculum cross-reference, not a verified JAMB, WAEC or NECO syllabus statement. Confirm against the relevant examination-body syllabus before marking as aligned.',
 true,t.sort_order
from public.external_exam_subjects s
join public.external_exam_topics t on t.subject_id=s.id and t.is_published
where s.is_active and (
 (s.exam_code='JAMB' and s.name in ('Use of English','Mathematics','Biology','Chemistry','Physics')) or
 (s.exam_code='WAEC' and s.name in ('English Language','General Mathematics','Biology','Chemistry','Physics')) or
 (s.exam_code='NECO' and s.name in ('English Language','General Mathematics','Biology','Chemistry','Physics'))
)
and not exists (
 select 1 from public.external_exam_syllabus_entries e
 where e.source_id=(select id from public.external_exam_sources where source_url='https://nerdc.gov.ng/content_manager/new_senior_curriculum_home.html' limit 1)
 and e.exam_code=s.exam_code and e.subject_id=s.id and e.linked_topic_id=t.id and e.entry_kind='topic' and e.title=t.title
);

commit;